// The readings port built from the picture measures (readings.ts), on the recorded answers of the real picture function
// (test/fixtures/picture-captured.json: punch, punch-offcentre, loop and drift, generated by ffmpeg 6.1.1). No test here calls a
// live API. The generated clips are checked end to end in media/picture.test.ts.

import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import { describe, it } from "node:test";
import { EngineError } from "../contracts/errors.ts";
import { pictureResultSchema, type PictureResult } from "../../../functions/ffmpeg/types.ts";
import type { PictureClient, PictureRequest } from "../media/index.ts";
import { pictureReadings } from "./readings.ts";
import type { ReadingsScope } from "./reference.ts";

const FIXTURE = join(
  dirname(fileURLToPath(import.meta.url)),
  "test",
  "fixtures",
  "picture-captured.json",
);
const captured = JSON.parse(readFileSync(FIXTURE, "utf8")) as { results: Record<string, unknown> };

/** One recorded answer, checked against the picture contract (a fixture that no longer matches fails here, not later). */
function recorded(kind: string): PictureResult {
  return pictureResultSchema.parse(captured.results[kind]);
}

/** A picture client that answers with one recorded result and records each request. */
function replaying(result: PictureResult): { client: PictureClient; requests: PictureRequest[] } {
  const requests: PictureRequest[] = [];
  return {
    requests,
    client: async (request) => {
      requests.push(request);
      return result;
    },
  };
}

function scope(overrides: Partial<ReadingsScope> = {}): ReadingsScope {
  return {
    organizationId: "ws_test",
    requestId: "req_01JABCDEFGHJKMNPQRSTVWXYZ0",
    reservationId: "res_01JABCDEFGHJKMNPQRSTVWXYZ0",
    attempt: 1,
    source: { kind: "url", url: "https://media.example.test/reels/fixture-0001.mp4" },
    durationMs: 2000,
    cutsMs: [],
    frames: [],
    ...overrides,
  };
}

describe("the readings from the picture measures (analyze/readings.ts)", () => {
  it("reads the centred zoom-in of the punch clip as one jump at 1000 ms of about 1.2, and no loop", async () => {
    const { client } = replaying(recorded("punch"));
    const readings = await pictureReadings(client)(scope());
    assert.equal(
      readings.captions,
      null,
      "captions are not read here (the vision reader is not built)",
    );
    assert.equal(readings.loop, false);
    assert.ok(readings.zoom !== null);
    assert.equal(readings.zoom?.jumps.length, 1);
    assert.equal(readings.zoom?.jumps[0]?.atMs, 1000);
    assert.ok(Math.abs((readings.zoom?.jumps[0]?.scale ?? 0) - 1.2) <= 0.02);
  });

  it("reads the off-centre zoom-in the same way", async () => {
    const { client } = replaying(recorded("punch-offcentre"));
    const readings = await pictureReadings(client)(scope());
    assert.equal(readings.zoom?.jumps[0]?.atMs, 1000);
    assert.ok(Math.abs((readings.zoom?.jumps[0]?.scale ?? 0) - 1.2) <= 0.03);
  });

  it("reads a looping picture as a loop, with no zoom jump", async () => {
    const { client } = replaying(recorded("loop"));
    const readings = await pictureReadings(client)(scope());
    assert.equal(readings.loop, true);
    assert.deepEqual(readings.zoom?.jumps, []);
  });

  it("reads a drifting picture as not looping", async () => {
    const { client } = replaying(recorded("drift"));
    const readings = await pictureReadings(client)(scope());
    assert.equal(readings.loop, false);
  });

  it("leaves shake and speed ramps null: they have no measurement yet, so the grammar's motion stays unknown", async () => {
    const { client } = replaying(recorded("punch"));
    const readings = await pictureReadings(client)(scope());
    assert.equal(readings.zoom?.shake, null);
    assert.equal(readings.zoom?.speedRamps, null);
  });

  it("sends the source and the scene cuts of the scope to the picture function", async () => {
    const { client, requests } = replaying(recorded("loop"));
    const source = { kind: "url" as const, url: "https://media.example.test/reels/other.mp4" };
    await pictureReadings(client)(scope({ source, cutsMs: [500, 1500] }));
    assert.deepEqual(requests, [{ source, cutsMs: [500, 1500] }]);
  });

  it("reports no zoom reading when every pair straddles a cut (not measured, not zero)", async () => {
    const allCut = pictureResultSchema.parse({
      ...recorded("loop"),
      pairs: recorded("loop").pairs.map((pair) => ({
        ...pair,
        usable: false,
        scale: null,
        fit: null,
      })),
    });
    const readings = await pictureReadings(replaying(allCut).client)(scope());
    assert.equal(readings.zoom, null);
    assert.equal(
      readings.loop,
      true,
      "the loop is still measured from the first and last frame (the loop clip)",
    );
  });

  it("lets a failed picture call throw: the stage fails, nothing is guessed", async () => {
    const failing: PictureClient = async () => {
      throw new EngineError("provider", "media function /picture failed (HTTP 503)", {
        retryable: true,
        stage: "media.picture",
      });
    };
    await assert.rejects(
      pictureReadings(failing)(scope()),
      (error: unknown) => error instanceof EngineError && error.retryable,
    );
  });
});
